    'AssetValuationDesc'                  => 'Configureer de waarderingsschaal voor activa en de waarderingsoverrides per actief.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Gebruikers toevoegen, bewerken, uitschakelen en opnieuw instellen; wachtwoordbeleid beheren.',
    'RoleManagementDesc'                  => 'Definieer rollen en de bijbehorende machtigingen.',
    'TeamManagementDesc'                  => 'Teams maken en beheren die worden gebruikt voor het filteren van recordzichtbaarheid.',
    'SeparationExtraDesc'                 => 'De Team-Based Separation Extra beperkt de zichtbaarheid van risico\'s tot alleen de gebruikers die lid zijn van het team waaraan het risico is toegewezen. In het SimpleRisk Core-product kan, zonder deze Extra, elke gebruiker elk risico zien.',
    'CustomAuthenticationExtraDesc'       => 'De Extra Custom Authentication biedt ondersteuning voor Active Directory- en SAML-authenticatie. In het SimpleRisk Core-product is zonder deze Extra de enige optie het aanmaken van nieuwe gebruikers in de identiteitsopslag van SimpleRisk.',
    'EncryptionExtraDesc'                 => 'De Extra Encrypted Database genereert een willekeurige AES-256-bits versleutelingssleutel en gebruikt die om gevoelige tekst te versleutelen voordat deze in de SimpleRisk-database wordt ingevoegd. Zo kan niemand de gegevens bekijken of wijzigen zonder de SimpleRisk-toepassing rechtstreeks te gebruiken.',
    'OrganizationManagementDesc'          => "Met de extra optie 'Organisatiehiërarchie' kunt u meerdere bedrijfseenheden definiëren die elk een willekeurig aantal teams kunnen omvatten. Gebruikers kunnen vervolgens worden toegewezen aan een of meer teams binnen verschillende bedrijfseenheden. Dit heeft gevolgen voor de mogelijkheid van een gebruiker om de teams, gebruikers en middelen te zien en te gebruiken waaraan hij of zij niet is gekoppeld.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Verwijder risico\'s in bulk. Gebruik het spaarzaam, want verwijderingen zijn permanent.',
    'AuditTrailDesc'                      => 'Zoek en exporteer het systeemauditlogboek van gebruikersacties.',
    'ImportExportExtraDesc'               => 'Met de Extra Import-Export kunt u gegevens in SimpleRisk importeren door velden in een CSV-bestand te koppelen aan velden in de SimpleRisk-database. Hiermee kunt u auditresultaten uit een spreadsheet van derden, resultaten van kwetsbaarheidsscans uit een andere tool, activa uit uw CMDB en meer importeren. De Extra biedt ook de mogelijkheid om CSV-bestanden uit SimpleRisk te exporteren met risico\'s, mitigaties, beoordelingen of een gecombineerd rapport van alle drie.',
    'JiraExtraDesc'                       => 'De Jira Integration Extra biedt gebruikers de mogelijkheid om bidirectioneel te integreren met een Jira-instantie. Hiermee kunnen risico\'s worden gekoppeld aan Jira-issues en kunnen hun gegevens, status en opmerkingen worden gesynchroniseerd.',
    'APIExtraDesc'                        => 'Met de Extra API kunnen klanten een RESTful API gebruiken om gescripte interacties met andere toepassingen te maken, voor geavanceerde automatisering en benutting van bestaande infrastructuur.',
    'AdvancedSearchExtraDesc'             => 'De Extra Advanced Search verandert het zoekvak in de bovenbalk in één zoekopdracht over risico\'s, frameworks, beheersmaatregelen, documenten, uitzonderingen, tests, audits, activa en activagroepen, met een volledige zoekpagina om de resultaten door te werken. Er worden alleen records getoond die de gebruiker mag zien.',
    'AssessmentsExtraDesc'                => 'Met Risk Assessment Extra kunnen gebruikers contactpersonen definiëren, vragen opstellen (inclusief logica), meerdere vragen samenstellen met behulp van een vragenlijstsjabloon, vragenlijsten maken en naar contactpersonen versturen, de resultaten van de vragenlijst bekijken, risico\'s toevoegen op basis van die resultaten, de resultaten in de loop van de tijd vergelijken, extern aangepaste beoordelingen importeren en exporteren en het auditspoor van de risicobeoordeling bekijken.',
    'ActiveAssessmentsDesc'               => 'Beoordelingen die momenteel lopen bekijken en beheren.',
    'WorkflowsExtraDesc'                  => 'De Workflows Extra biedt een visuele, gebeurtenisgestuurde workflow-engine die risicobeheeracties automatiseert als reactie op gebeurtenissen binnen SimpleRisk. U kunt workflows ontwerpen die worden geactiveerd bij wijzigingen, zoals het indienen, bijwerken of beoordelen van een risico, om goedkeuringen te routeren, taken toe te wijzen en uw proces gaande te houden zonder handmatige tussenkomst.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'De Secure Controls Framework (SCF) Extra is een directe integratie tussen het Secure Controls Framework en SimpleRisk. Deze importeert de catalogus van beheersmaatregelen van de SCF en de mappings ervan naar een breed scala aan compliance- en cybersecurityframeworks in de Governance-functionaliteit van SimpleRisk, zodat u de frameworks die u nodig hebt kunt overnemen en de bijbehorende beheersmaatregelen kunt beheren zonder ze handmatig op te bouwen.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migreer de oude varchar-kolommen voor beoordelingsdatums naar de juiste datumtypen. Alleen zichtbaar wanneer nodig.',
    'DatabaseUpgradeDesc'                 => 'Start handmatig de upgraderoutine van de SimpleRisk-database.',

