    'EncryptionMissingLockTablesPrivilegeUi' => 'De SimpleRisk-databasegebruiker heeft niet het LOCK TABLES-privilege dat vereist is voor versleuteling. Een databasebeheerder moet uitvoeren: GRANT LOCK TABLES ON {$db}.* TO {$user}; en het daarna opnieuw proberen.',
    'EncryptionRequiredGrantLabel' => 'Vereiste GRANT-instructie:',
