    'RestoreFromBackup'                     => 'Herstellen vanuit back-up',
    'RestoreFromBackupNotYetAvailable'      => 'Herstellen vanuit back-up is nog niet beschikbaar in deze build. Neem contact op met SimpleRisk-ondersteuning om te herstellen.',
