    'EncryptionBackupStateRestoring'        => 'Er wordt momenteel een herstelproces uitgevoerd.',
    'EncryptionNoBackupAvailable'           => 'Er is momenteel geen back-up van vóór de activering opgeslagen. De back-up wordt aan het begin van elke activering aangemaakt en overschreven door elke volgende activering of deactivering.',
    'EncryptionRestoreCtaHelp'              => 'Kies deze optie als er tijdens de validatie problemen zijn gevonden en u wilt terugkeren naar de staat van vóór de versleuteling.',
    'EncryptionRestoreTitle'                => 'Herstellen vanuit een back-up?',
    'EncryptionRestoreBodyWhy'              => 'Er wordt teruggekeerd naar de momentopname van vóór de versleuteling, die is gemaakt aan het begin van de meest recente activering. Kies dit als uw validatie na de activering problemen heeft gevonden en u de versleuteling wilt afbreken.',
    'EncryptionRestoreBodyWhat'             => 'Elke rij die na het aanmaken van de back-up naar de database is geschreven, gaat permanent verloren, inclusief risico\'s, mitigaties, items in het auditlogboek en alle andere wijzigingen sinds de activering. De Extra Versleutelde database wordt als onderdeel van het herstel gedeactiveerd.',
    'EncryptionDeleteBackupCta'             => 'De back-up van vóór de versleuteling verwijderen',
    'EncryptionDeleteBackupCtaHelp'         => 'Kies deze optie zodra de validatie na de versleuteling is voltooid. Het verwijderen van de onversleutelde momentopname zorgt ervoor dat de versleuteling daadwerkelijk bescherming biedt.',
    'EncryptionDeleteBackupTitle'           => 'De back-up van vóór de versleuteling verwijderen?',
    'EncryptionDeleteBackupBodyWhy'         => 'De onversleutelde momentopname van uw gegevens, gemaakt aan het begin van de meest recente activering, wordt verwijderd. Deze onbeperkt bewaren ondermijnt het doel van versleuteling: iedereen met toegang tot de database kan de kopie van vóór de versleuteling lezen.',
    'EncryptionDeleteBackupBodyWhat'        => 'De back-up in de database wordt onmiddellijk verwijderd. U kunt Herstellen vanuit back-up dan niet meer gebruiken om de database terug te zetten naar de staat van vóór de versleuteling. Als u later problemen met de versleuteling vaststelt, is uw enige herstelmogelijkheid een nieuw databaseherstel vanuit uw operationele back-ups.',
    'EncryptionDeleteBackupError'           => 'Het verwijderen van de back-up is mislukt. Controleer het foutopsporingslogboek en probeer het opnieuw.',
