    'AssetScoring' => 'Assetscoring',
    'AssetScoringSettingsHint' => 'Elk asset wordt beoordeeld als Laag, Gemiddeld of Hoog voor vertrouwelijkheid, integriteit en beschikbaarheid. Vertrouwelijkheid kan in plaats daarvan Niet van toepassing zijn, waardoor die buiten beide resultaten blijft. De FIPS-categorisering is de hoogste van de drie beoordelingen. De gewogen score is het gewogen gemiddelde van de drie niveauwaarden, en de drempelwaarden voor de bandbreedtes zetten die score om in een bandbreedte Laag, Gemiddeld of Hoog. Als u deze instellingen wijzigt, worden alle assets direct opnieuw gescoord.',
